<?php
declare(strict_types=1);
require dirname(__DIR__).'/app/bootstrap.php';
if(PHP_SAPI!=='cli'){http_response_code(403);exit(1);} $args=$argv;array_shift($args);$execute=in_array('--execute',$args,true);$confirm=null;$group=null;foreach($args as $a){if(str_starts_with($a,'--confirm='))$confirm=substr($a,10);if(str_starts_with($a,'--group='))$group=substr($a,8);}
$config=Hls\Config::load();if($config['database']!=='hls_v2')throw new RuntimeException('Script hanya boleh untuk hls_v2.');$db=Hls\Database::connect($config);
$targets=['assets'=>[['md_assets',1,'DEMO-TRUCK-01'],['md_assets',2,'DEMO-EQUIP-01']],'parties'=>[['md_parties',1,'DEMO-SENDER-01'],['md_parties',2,'DEMO-RECEIVER-01']],'personnel'=>[['md_personnel',1,'DEMO-DRIVER-01'],['md_personnel',2,'DEMO-OPERATOR-01']],'routes'=>[['md_routes',1,'DEMO-ROUTE-01']],'locations'=>[['md_locations',1,'DEMO-LOC-A'],['md_locations',2,'DEMO-LOC-B']],'inventory'=>[['md_items',1,'DEMO-ITEM'],['md_categories',1,'DEMO-CAT'],['md_units',1,'DEMO-UNIT']]];
if(!$execute){echo "DRY-RUN (default); no database changes\n";foreach($targets as $name=>$rows){if($group&&$group!==$name)continue;foreach($rows as [$t,$id,$code]){$q=$db->prepare("SELECT id,code FROM `$t` WHERE id=? AND code=?");$q->execute([$id,$code]);echo json_encode(['group'=>$name,'table'=>$t,'id'=>$id,'code'=>$code,'match'=>(bool)$q->fetch(PDO::FETCH_ASSOC)],JSON_UNESCAPED_UNICODE)."\n";}}echo "Use --execute --group=<group> --confirm=DEMO-CLEANUP-APPROVED only after explicit approval.\n";exit(0);}
if($confirm!=='DEMO-CLEANUP-APPROVED'||!in_array($group,['assets','parties','personnel'],true))throw new RuntimeException('Execution requires explicit confirmation and only approved orphan groups.');
$columns=['assets'=>['asset_id'],'parties'=>['party_id','sender_id','receiver_id'],'personnel'=>['personnel_id','driver_id','operator_id']];$db->beginTransaction();try{$deleted=0;foreach($targets[$group] as [$t,$id,$code]){$q=$db->prepare("SELECT id FROM `$t` WHERE id=? AND code=? FOR UPDATE");$q->execute([$id,$code]);if(!$q->fetch())throw new RuntimeException("Target berubah/tidak cocok: $t#$id");$fk=$db->prepare("SELECT TABLE_NAME,COLUMN_NAME FROM information_schema.KEY_COLUMN_USAGE WHERE REFERENCED_TABLE_SCHEMA=DATABASE() AND REFERENCED_TABLE_NAME=?");$fk->execute([$t]);foreach($fk as $f){$s=$db->prepare("SELECT COUNT(*) FROM `{$f['TABLE_NAME']}` WHERE `{$f['COLUMN_NAME']}`=?");$s->execute([$id]);if((int)$s->fetchColumn()>0)throw new RuntimeException("Dependensi FK ditemukan: {$f['TABLE_NAME']}.{$f['COLUMN_NAME']}");}foreach($columns[$group] as $col){$tables=$db->query('SHOW TABLES')->fetchAll(PDO::FETCH_COLUMN);foreach($tables as $child){if($child===$t)continue;$has=$db->query('SHOW COLUMNS FROM `'.$child.'` LIKE "'.$col.'"')->fetch();if(!$has)continue;$s=$db->prepare("SELECT COUNT(*) FROM `$child` WHERE `$col`=?");$s->execute([$id]);if((int)$s->fetchColumn()>0)throw new RuntimeException("Dependensi non-FK ditemukan: $child.$col");}}$del=$db->prepare("DELETE FROM `$t` WHERE id=? AND code=?");$del->execute([$id,$code]);$deleted+=$del->rowCount();}$db->commit();echo "Deleted $deleted records\n";}catch(Throwable $e){$db->rollBack();fwrite(STDERR,$e->getMessage().PHP_EOL);exit(1);}


